{
  "passageId": "mrna-vaccine-lipid-nanoparticle",
  "items": [
    {
      "id": "R1",
      "type": "PROCESS",
      "otherName": "",
      "reason": "유전 정보가 mRNA로 전사된 다음 그 mRNA가 세포질로 이동하는 단계적 순서이다."
    },
    {
      "id": "R2",
      "type": "PROCESS",
      "otherName": "",
      "reason": "세포질로 이동한 mRNA를 바탕으로 단백질 합성이 진행되는 다음 단계를 제시한다."
    },
    {
      "id": "R3",
      "type": "PROCESS",
      "otherName": "",
      "reason": "바이러스의 유전 물질을 mRNA로 바꾼 뒤 이를 이용해 숙주가 단백질을 합성하는 순서이다."
    },
    {
      "id": "R4",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "앞에서 설명한 mRNA를 통한 단백질 합성 원리를 바이러스의 증식 방식에 적용한다."
    },
    {
      "id": "R5",
      "type": "CAUSE",
      "otherName": "",
      "reason": "합성된 바이러스 단백질이 항원으로 인식되어 항체와 기억 세포를 만드는 면역 반응을 일으킨다."
    },
    {
      "id": "R6",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "항원에 대한 면역 반응과 기억 세포 생성이 가능하다는 사실로부터 백신으로 감염에 대비할 수 있다는 판단을 도출한다."
    },
    {
      "id": "R7",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "백신의 일반적인 예방 방식을 그 하위 사례인 mRNA 백신의 접종 물질과 작동 방식으로 구체화한다."
    },
    {
      "id": "R8",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "접종 물질이 바이러스인지 여부를 기준으로 기존 백신과 mRNA 백신의 차이를 제시한다."
    },
    {
      "id": "R9",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "mRNA 백신이 바이러스가 아니라는 사실을 근거로 접종에 따른 바이러스 감염 위험이 없다고 판단한다."
    },
    {
      "id": "R10",
      "type": "DEFINITION",
      "otherName": "",
      "reason": "체내 효소에 쉽게 분해된다는 성질을 뒤 문장에서 체내 불안정성이라는 표현으로 다시 말한다."
    },
    {
      "id": "R11",
      "type": "CAUSE",
      "otherName": "",
      "reason": "mRNA의 불안정성과 큰 분자 크기 및 음전하가 세포 흡수를 어렵게 하는 실제 요인으로 제시된다."
    },
    {
      "id": "R12",
      "type": "CONCESSION",
      "otherName": "",
      "reason": "동일한 mRNA 백신에 감염 위험이 없다는 장점이 있지만 안정성과 세포 전달에는 한계가 있음을 제시한다."
    },
    {
      "id": "R13",
      "type": "PROBLEM_RESPONSE",
      "otherName": "",
      "reason": "mRNA의 불안정성과 전달에 불리한 성질을 보완하는 장치로 지질 나노 입자를 실제로 이용한다."
    },
    {
      "id": "R14",
      "type": "PROBLEM_RESPONSE",
      "otherName": "",
      "reason": "mRNA가 세포에 거의 흡수되지 않는 문제에 대해 지질 나노 입자라는 전달 장치를 제시한다."
    },
    {
      "id": "R15",
      "type": "CAUSE",
      "otherName": "",
      "reason": "지질을 이루는 지방산의 성질이 지질의 소수성을 결정하는 물질적 원인으로 제시된다."
    },
    {
      "id": "R16",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "물이 친수성 물질과만 섞인다는 혼합 원리를 근거로 지질이 물과 섞이지 않는 이유를 설명한다."
    },
    {
      "id": "R17",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "소수성 물질끼리만 섞인다는 원리가 지질의 소수성을 설명하는 근거로 제시된다."
    },
    {
      "id": "R18",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "소수성 꼬리와 전하를 띤 머리를 함께 갖는 구조를 근거로 인지질을 양친매성 물질이라고 판단한다."
    },
    {
      "id": "R19",
      "type": "CAUSE",
      "otherName": "",
      "reason": "인지질의 양친매성 때문에 친수성 머리가 세포 안팎의 수용액에 접하는 배열이 형성된다."
    },
    {
      "id": "R20",
      "type": "CAUSE",
      "otherName": "",
      "reason": "인지질의 소수성 부분과 소수성 분자 간 인력이 꼬리들이 서로 모이는 배열을 형성한다."
    },
    {
      "id": "R21",
      "type": "CAUSE",
      "otherName": "",
      "reason": "친수성 머리의 배치를 포함한 세포막의 인지질 배열이 친수성 물질의 투과를 차단한다."
    },
    {
      "id": "R22",
      "type": "CAUSE",
      "otherName": "",
      "reason": "소수성 꼬리가 모여 형성한 세포막 구조가 친수성 물질의 투과를 차단한다."
    },
    {
      "id": "R23",
      "type": "DEVELOPMENT",
      "otherName": "",
      "reason": "지질 나노 입자의 이용을 제시한 뒤 그 재료인 지질의 성질을 설명하는 논의로 옮겨 간다."
    },
    {
      "id": "R24",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "양이온성 지질로 둘러싸인 mRNA가 세포막과 반발하지 않는다는 설명이 전기적 반발을 막을 수 있다는 판단을 뒷받침한다."
    },
    {
      "id": "R25",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "세포막 인산기 머리가 음전하를 띤다는 구조적 사실이 양이온성 지질의 반발 방지 효과를 설명하는 근거가 된다."
    },
    {
      "id": "R26",
      "type": "PROBLEM_RESPONSE",
      "otherName": "",
      "reason": "mRNA의 음전하로 생기는 전달상의 문제에 대해 양이온성 지질로 둘러싸 반발을 막는 대응을 제시한다."
    },
    {
      "id": "R27",
      "type": "CONCESSION",
      "otherName": "",
      "reason": "같은 양이온성 지질이 실험실에서는 효과가 있지만 체내에서는 효과가 제한된다는 한계를 제시한다."
    },
    {
      "id": "R28",
      "type": "CAUSE",
      "otherName": "",
      "reason": "양이온성 지질에 혈장 단백질이 흡착되는 현상이 mRNA의 세포막 투과를 제한한다."
    },
    {
      "id": "R29",
      "type": "PROBLEM_RESPONSE",
      "otherName": "",
      "reason": "양이온성 지질의 체내 전달 한계를 해결하기 위해 대체 재료인 이온화 지질을 도입한다."
    },
    {
      "id": "R30",
      "type": "CAUSE",
      "otherName": "",
      "reason": "낮은 pH에서의 높은 수소 이온 농도가 이온화 지질의 양이온화를 일으킨다."
    },
    {
      "id": "R31",
      "type": "CONDITION",
      "otherName": "",
      "reason": "용액의 pH가 낮은지 높은지에 따라 이온화 지질의 전하 상태가 양이온성과 중성으로 갈린다."
    },
    {
      "id": "R32",
      "type": "CAUSE",
      "otherName": "",
      "reason": "이온화 지질이 수소 이온을 적게 받아들이는 것이 전기적으로 중성이 되는 원인이다."
    },
    {
      "id": "R33",
      "type": "CAUSE",
      "otherName": "",
      "reason": "이온화 지질의 전기적 중성 상태가 혈장 단백질의 흡착을 막는다."
    },
    {
      "id": "R34",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "pH에 따라 이온화 지질의 전하가 달라지는 원리를 중성 복합체의 제조에 적용한다."
    },
    {
      "id": "R35",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "혈장 단백질의 흡착 여부를 기준으로 양이온성 지질과 중성화된 이온화 지질의 차이를 제시한다."
    },
    {
      "id": "R36",
      "type": "PROCESS",
      "otherName": "",
      "reason": "중성 복합체를 형성한 다음 그 복합체가 세포막 수용체에 결합하는 단계로 이어진다."
    },
    {
      "id": "R37",
      "type": "PROCESS",
      "otherName": "",
      "reason": "복합체가 수용체에 결합하는 단계를 거쳐 내포 작용으로 세포 내부에 들어가는 순서이다."
    },
    {
      "id": "R38",
      "type": "DEFINITION",
      "otherName": "",
      "reason": "복합체의 진입 방식으로 제시된 내포 작용이 어떤 현상인지 뜻을 풀어 설명한다."
    },
    {
      "id": "R39",
      "type": "CAUSE",
      "otherName": "",
      "reason": "내포 작용에 따른 세포막의 함입이 세포질 안에 엔도솜 구조체를 형성한다."
    },
    {
      "id": "R40",
      "type": "PROCESS",
      "otherName": "",
      "reason": "엔도솜이 형성된 뒤 그 내부가 산성화되는 다음 단계가 진행된다."
    },
    {
      "id": "R41",
      "type": "CAUSE",
      "otherName": "",
      "reason": "엔도솜 내부의 산성화가 엔도솜 막을 불안정하게 만든다."
    },
    {
      "id": "R42",
      "type": "CAUSE",
      "otherName": "",
      "reason": "엔도솜 막의 불안정성이 mRNA의 세포질 방출을 일으킨다."
    },
    {
      "id": "R43",
      "type": "PROCESS",
      "otherName": "",
      "reason": "앞 단계에서 방출된 mRNA를 바탕으로 리보솜 결합과 단백질 합성 단계가 진행된다."
    },
    {
      "id": "R44",
      "type": "CAUSE",
      "otherName": "",
      "reason": "합성된 바이러스 단백질이 면역 반응과 기억 세포 생성을 유도하여 감염에 대비하게 한다."
    },
    {
      "id": "R45",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "기억 세포를 통해 재침입에 대비한다는 일반 면역 원리를 mRNA 백신의 예방 효과에 적용한다."
    },
    {
      "id": "R46",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "mRNA 백신의 단백질 합성과 면역 유도 과정을 리보솜 결합 및 기억 세포 생성으로 더 자세히 설명한다."
    },
    {
      "id": "R47",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "pH의 의미와 산성 기준이 pH에 따른 수소 이온 농도 및 이온화 지질의 전하 변화를 설명하는 근거가 된다."
    }
  ]
}

